  "title_novice": "Водоотдача раствора: оптимум 4–8 см³/ч",
  "summary": [
    {"text": "Водоотдача — основной показатель качества глинистого раствора: чем она ниже, тем лучше раствор для ГИС.", "claims": ["c1"]},
    {"text": "При оптимальной водоотдаче 4—8 см³/ч глубина проникновения и толщина глинистой корки в коллекторах минимальны.", "claims": ["c2"]},
    {"text": "При высокой водоотдаче (20 см³/ч) условия для ГИС крайне неблагоприятны: страдают и глубинные, и малоглубинные методы.", "claims": ["c5", "c6"]}
  ],
  "claims": [
    {"key": "c0", "text": "Особенности вскрытия коллектора (зона проникновения, корка) зависят от параметров раствора: водоотдачи, плотности, минерализации фильтрата.", "kind": "observation", "unit_id": "u-090-6c1318", "page": 90, "quote": "Проявление этих особенностей зависит от параметров раствора: водоотдачи, плотности, минерализации фильтрата.", "numbers": [], "question": null},
    {"key": "c1", "text": "Водоотдача — главный показатель качества глинистого раствора; чем она ниже, тем раствор лучше.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "Водоотдача - основной показатель качества глинистого раствора; чем ниже водоотдача, тем лучше раствор.", "numbers": [], "question": null},
    {"key": "c2", "text": "При оптимальной водоотдаче 4—8 см³/ч условия для ГИС наиболее благоприятны, потому что проникновение и корка минимальны.", "kind": "observation", "unit_id": "u-090-6c1318", "page": 90, "quote": "При оптимальной водоотдаче (4—8 см³/ч) условия изучения разреза геофизическими методами наиболее благоприятны, поскольку в этом случае глубина проникновения и толщина глинистой корки в коллекторах являются минимальными.", "numbers": ["4", "8"], "question": null},
    {"key": "c3", "text": "Минимальное проникновение даёт надёжное определение параметров неизменённой части коллектора методами электрометрии.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "Это обеспечивает надежное определение параметров неизмененной части коллектора методами электрометрии", "numbers": [], "question": null},
    {"key": "c4", "text": "Коллекторские свойства определяют методами с высокой вертикальной разрешающей способностью и малой глубинностью: ГГМ, МБК, ЯМР.", "kind": "inference", "unit_id": "u-090-6c1318", "page": 90, "quote": "коллекторских свойств пласта методами с высокой вертикальной разрешающей способностью и малой глубинностью (ГГМ, МБК, ЯМР)", "numbers": [], "question": null},
    {"key": "c5", "text": "При высокой водоотдаче (20 см³/ч) глубокое проникновение мешает оценивать продуктивность глубинными методами электрометрии.", "kind": "observation", "unit_id": "u-090-6c1318", "page": 90, "quote": "глубокое проникновение не позволяет оценивать продуктивность коллектора наиболее глубинными методами электрометрии (индукционный зонд, большие потенциал- и градиент-зонды)", "numbers": ["20"], "question": null},
    {"key": "c6", "text": "При высокой водоотдаче толстая корка делает коллектор недоступным для малоглубинных методов ГГМ, МБК, ЯМР.", "kind": "observation", "unit_id": "u-090-6c1318", "page": 90, "quote": "а толстая глинистая корка делает коллектор недоступным для изучения методами с малой глубинностью (ГГМ, МБК, ЯМР)", "numbers": [], "question": null},
    {"key": "c7", "text": "Высокая водоотдача (20 см³/ч) делает условия изучения разреза, прежде всего коллекторов, крайне неблагоприятными.", "kind": "observation", "unit_id": "u-090-6c1318", "page": 90, "quote": "При высокой водоотдаче (20 см³/ч) условия изучения разреза и прежде всего коллекторов геофизическими методами становятся крайне неблагоприятными", "numbers": ["20"], "question": null}
  ],
  "mechanism": [
    {"text": "Раствор отдаёт воду в проницаемый пласт. Чем больше отдача, тем глубже проникновение и толще глинистая корка.", "claims": ["c0", "c2", "c5", "c6"], "hypothesis": false},
    {"text": "Физически водоотдача — объём воды, отфильтровавшийся из раствора в пласт за единицу времени при стандартном опыте.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист по водоотдаче раствора судит, какие методы сработают. При 4—8 см³/ч можно опираться и на глубинную электрометрию, и на ГГМ, МБК, ЯМР.", "claims": ["c2", "c3", "c4"], "hypothesis": false},
    {"text": "При 20 см³/ч глубинные методы не оценят продуктивность, а малоглубинные не увидят коллектор через корку.", "claims": ["c5", "c6", "c7"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Водоотдача — не единственный параметр: на проявление зон проникновения и корок влияют также плотность раствора и минерализация фильтрата.", "claims": ["c0"], "hypothesis": false}
  ],
  "deeper": [],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Оптимальная водоотдача: 4—8 см³/ч — проникновение и корка минимальны.", "claims": ["c2"]},
    {"text": "Высокая водоотдача: 20 см³/ч — условия крайне неблагоприятны.", "claims": ["c7"]}
  ],
  "terms_defined": [
    {"term": "водоотдача", "term_en": "fluid loss / filtration rate", "abbr": "", "definition": "Показатель того, сколько жидкости раствор отдаёт в пласт. Основной показатель качества глинистого раствора: чем ниже, тем лучше.", "claims": ["c1"]},
    {"term": "глубина проникновения", "term_en": "invasion depth", "abbr": "", "definition": "Насколько далеко от скважины в пласт вошёл фильтрат раствора.", "claims": ["c2"]},
    {"term": "глубинность метода", "term_en": "depth of investigation", "abbr": "", "definition": "Как далеко от стенки скважины в пласт «видит» метод. У ГГМ, МБК, ЯМР она малая, у индукционного зонда — большая.", "claims": ["c4", "c5"]},
    {"term": "вертикальная разрешающая способность", "term_en": "vertical resolution", "abbr": "", "definition": "Способность метода различать тонкие слои по глубине скважины.", "claims": ["c4"]},
    {"term": "электрометрия", "term_en": "electrical logging", "abbr": "", "definition": "Группа методов измерения электрического сопротивления пород: индукционный зонд, потенциал- и градиент-зонды.", "claims": ["c3", "c5"]},
    {"term": "неизменённая часть пласта", "term_en": "uninvaded zone", "abbr": "", "definition": "Часть пласта за зоной проникновения, куда фильтрат не дошёл.", "claims": ["c3"]}
  ],
